  readonly Dictionary<string,string> settingsEdits=new Dictionary<string,string>();bool renderingSettings,settingsConflict;DateTime settingsPoll=DateTime.MinValue;
  void AddSettingsPage(TabControl tabs){
   settingsTab=new TabPage("Viewpoint 中文设置"){BackColor=bg,ForeColor=fg};tabs.TabPages.Add(settingsTab);var layout=new TableLayoutPanel{Dock=DockStyle.Fill,ColumnCount=1,RowCount=5,Padding=new Padding(12)};layout.RowStyles.Add(new RowStyle(SizeType.Absolute,39));layout.RowStyles.Add(new RowStyle(SizeType.Absolute,33));layout.RowStyles.Add(new RowStyle(SizeType.Percent,100));layout.RowStyles.Add(new RowStyle(SizeType.Absolute,70));layout.RowStyles.Add(new RowStyle(SizeType.Absolute,43));settingsTab.Controls.Add(layout);
   var mainLayout=(TableLayoutPanel)Controls[0];for(int index=0;index<mainLayout.Controls.Count;index++)mainLayout.SetCellPosition(mainLayout.Controls[index],new TableLayoutPanelCellPosition(0,index));var hardwarePanel=mainLayout.GetControlFromPosition(0,2);float originalHardware=mainLayout.RowStyles[2].Height,originalLog=mainLayout.RowStyles[6].Height;tabs.SelectedIndexChanged+=(s,e)=>{if(launcherTabs!=null)return;bool focus=tabs.SelectedTab==settingsTab||tabs.SelectedIndex==2||tabs.SelectedTab.Text=="射击客户端实验";mainLayout.SuspendLayout();if(focus&&mainLayout.RowStyles[2].Height>0){originalHardware=mainLayout.RowStyles[2].Height;originalLog=mainLayout.RowStyles[6].Height;}hardwarePanel.Visible=!focus;log.Visible=!focus;mainLayout.RowStyles[2].Height=focus?0:originalHardware;mainLayout.RowStyles[6].Height=focus?0:originalLog;mainLayout.ResumeLayout(true);};
