   settingsGrid=new DataGridView{Dock=DockStyle.Fill,AllowUserToAddRows=false,AllowUserToDeleteRows=false,RowHeadersVisible=false,AutoGenerateColumns=false,BackgroundColor=card,EnableHeadersVisualStyles=false,SelectionMode=DataGridViewSelectionMode.FullRowSelect,MultiSelect=false,EditMode=DataGridViewEditMode.EditOnEnter,AutoSizeRowsMode=DataGridViewAutoSizeRowsMode.None,RowTemplate={Height=31}};settingsGrid.DefaultCellStyle.BackColor=card;settingsGrid.DefaultCellStyle.ForeColor=fg;settingsGrid.DefaultCellStyle.SelectionBackColor=Color.FromArgb(104,84,43);settingsGrid.DefaultCellStyle.SelectionForeColor=fg;settingsGrid.ColumnHeadersDefaultCellStyle.BackColor=Color.FromArgb(75,71,60);settingsGrid.ColumnHeadersDefaultCellStyle.ForeColor=fg;
   settingsGrid.Columns.Add(new DataGridViewTextBoxColumn{Name="category",HeaderText="分类",Width=165,ReadOnly=true});settingsGrid.Columns.Add(new DataGridViewTextBoxColumn{Name="name",HeaderText="中文名称 / 英文原名",Width=235,ReadOnly=true});settingsGrid.Columns.Add(new DataGridViewTextBoxColumn{Name="value",HeaderText="当前值（可编辑项双击修改）",Width=180});settingsGrid.Columns.Add(new DataGridViewTextBoxColumn{Name="key",HeaderText="原始参数",AutoSizeMode=DataGridViewAutoSizeColumnMode.Fill,ReadOnly=true});layout.Controls.Add(settingsGrid);
   settingsExplanation=new TextBox{Dock=DockStyle.Fill,Multiline=true,ReadOnly=true,ScrollBars=ScrollBars.Vertical,BackColor=card,ForeColor=fg};layout.Controls.Add(settingsExplanation);var actions=new FlowLayoutPanel{Dock=DockStyle.Fill,WrapContents=false};actions.Controls.Add(Button("保存修改（先退出游戏）",SaveSettings));actions.Controls.Add(Button("重新读取 / 放弃修改",()=>{if(settingsEdits.Count>0&&MessageBox.Show(this,"放弃软件里的未保存修改，读取游戏最新值？","重新读取",MessageBoxButtons.OKCancel,MessageBoxIcon.Question)!=DialogResult.OK)return;LoadSettings();}));actions.Controls.Add(Button("打开配置所在目录",()=>Links.Open(UserDir())));actions.Controls.Add(Button("快捷键使用说明",()=>MessageBox.Show(this,"默认 O：开启／关闭第一人称；SHIFT+O：切换第一／第三人称；DELETE：设置窗；F9：截图。\r\n\r\n这里显示的是文件中的实际绑定，不一定仍是默认键。LMENU=左 Alt，NEXT=Page Down，LSHIFT=左 Shift；+ 是组合键，逗号分隔备选键。空值表示解绑。\r\n\r\n自由镜头和其他功能请遵守服务器规则。没有核实的调试键只读。","Viewpoint 快捷键",MessageBoxButtons.OK,MessageBoxIcon.Information)));layout.Controls.Add(actions);
   settingsGroup.SelectedIndexChanged+=(s,e)=>{if(!renderingSettings)RenderSettings();};settingsSearch.TextChanged+=(s,e)=>{if(!renderingSettings)RenderSettings();};
