  void LoadSettings(){try{settingsStore=new ViewpointSettings(UserDir(),Path.Combine(data,"settings-backups"));settingsEdits.Clear();settingsConflict=false;string selected=Convert.ToString(settingsGroup.SelectedItem);renderingSettings=true;try{settingsGroup.Items.Clear();settingsGroup.Items.Add("常用可编辑设置");settingsGroup.Items.Add("全部参数（含只读）");foreach(string group in settingsStore.Values.Keys.Select(k=>SettingsCatalog.Group(k.Split(new[]{'|'},2)[1])).Distinct().OrderBy(k=>k))settingsGroup.Items.Add(group);settingsGroup.SelectedIndex=settingsGroup.Items.Contains(selected)?settingsGroup.Items.IndexOf(selected):0;}finally{renderingSettings=false;}RenderSettings();UpdateSettingsNotice();}catch(Exception e){settingsNotice.ForeColor=Color.FromArgb(255,133,117);settingsNotice.Text="设置读取失败，未修改任何文件："+e.Message;}}
  void RenderSettings(){
   if(settingsStore==null)return;settingsGrid.EndEdit();string group=Convert.ToString(settingsGroup.SelectedItem),search=settingsSearch.Text.Trim();renderingSettings=true;settingsGrid.SuspendLayout();
   try{settingsGrid.Rows.Clear();foreach(var p in settingsStore.Values.OrderBy(p=>SettingsCatalog.Group(p.Key.Split(new[]{'|'},2)[1])).ThenBy(p=>p.Key)){
    string key=p.Key.Split(new[]{'|'},2)[1];SettingInfo info=SettingsCatalog.Find(key);string category=SettingsCatalog.Group(key);bool editable=info!=null&&info.Kind!="readonly";
    if(group=="常用可编辑设置"&&!editable)continue;if(group!="常用可编辑设置"&&group!="全部参数（含只读）"&&group!=category)continue;string name=info==null?key:info.Name;
    if(search.Length>0&&(name+" "+key+" "+category+" "+SettingsCatalog.Description(key)).IndexOf(search,StringComparison.OrdinalIgnoreCase)<0)continue;
    string value;settingsEdits.TryGetValue(p.Key,out value);int index=settingsGrid.Rows.Add(category,name,value??p.Value,key);var row=settingsGrid.Rows[index];row.Tag=p.Key;row.Cells[2].ReadOnly=!editable;
    if(!editable)row.Cells[2].Style.ForeColor=Color.FromArgb(190,192,198);else if(info.Kind=="bool")row.Cells[2]=new DataGridViewComboBoxCell{DataSource=new[]{new SettingsChoice("false","关闭（false）"),new SettingsChoice("true","开启（true）")},DisplayMember="Text",ValueMember="Value",Value=value??p.Value,FlatStyle=FlatStyle.Flat};
    if(settingsEdits.ContainsKey(p.Key))row.Cells[2].Style.BackColor=Color.FromArgb(93,75,35);
   }}finally{settingsGrid.ResumeLayout();renderingSettings=false;}
  }
  void UpdateSettingsNotice(){if(settingsNotice==null)return;settingsNotice.ForeColor=settingsConflict?Color.FromArgb(255,133,117):fg;settingsNotice.Text=settingsConflict?"冲突：游戏或其他程序已修改文件。你的未保存修改已保留；请先核对，再点重新读取。保存已阻止。":settingsStore.Values.Count==0?"尚未生成设置文件：先正常加载 Viewpoint 并打开其设置，再重新读取。本页不会编造默认文件。":"已读取 "+settingsStore.Values.Count+" 项 · 可编辑 "+settingsStore.Values.Keys.Count(k=>{var info=SettingsCatalog.Find(k.Split(new[]{'|'},2)[1]);return info!=null&&info.Kind!="readonly";})+" 项 · 未保存修改 "+settingsEdits.Count+" 项\n游戏更改自动读取；有未保存修改时不覆盖。运行中也可保存并自动备份；多数修改下次启动或重载读取，文件被实际锁定时会报告错误。";}
  void PollSettings(){if(settingsStore==null||busy||(DateTime.Now-settingsPoll).TotalSeconds<2)return;settingsPoll=DateTime.Now;try{if(!settingsStore.Changed())return;if(settingsEdits.Count>0||settingsGrid.IsCurrentCellInEditMode){settingsConflict=true;UpdateSettingsNotice();}else LoadSettings();}catch{settingsNotice.Text="正在等待游戏完成写入设置文件，稍后会再次读取。";}}
  void SaveSettings(){settingsGrid.EndEdit();if(settingsStore==null)throw new Exception("尚未成功读取配置，请先重新读取。");if(settingsConflict)throw new Exception("存在外部修改冲突，请先重新读取并核对。");string message=settingsStore.Save(new Dictionary<string,string>(settingsEdits),false);LoadSettings();Write(message);MessageBox.Show(this,message,"Viewpoint 设置",MessageBoxButtons.OK,MessageBoxIcon.Information);}
 }
